document.addEventListener("DOMContentLoaded",()=>{const e=[{phase:1,title:"IDEATION",skills:["Business analysis","Market analysis","Product Research"],tools:["Miro","Figma","Google Analytics","SEMrush","SurveyMonkey"]},{phase:2,title:"DOCUMENTATION",skills:["Business Model","Game Design Document","Software Requirement Specification"],tools:["Notion","Confluence","Microsoft Word","Google Docs","Lucidchart"]},{phase:3,title:"MANAGEMENT",skills:["Project Management","Product Development","Business Development Management"],tools:["Jira","Trello","Asana","Slack","Microsoft Teams"]},{phase:4,title:"DEVELOPMENT",skills:["Unity","Python","Web dev","Java","LLM Server"],tools:["Visual Studio Code","Git/GitHub","Docker","AWS","Postman","Unity Editor"]},{phase:5,title:"TEST & REVIEW",skills:["Quality Assurance Test"],tools:["Selenium","Jest","Cypress","Jira","TestRail"]},{phase:6,title:"AI ENGINEERING",skills:["LLM Integration & Prompt Engineering","RAG (Retrieval-Augmented Generation)","Agentic Workflows & Multi-Agent Systems","Fine-tuning & Model Optimization","Vector Search & Embeddings","AI Application Architecture"],tools:["Python","PyTorch","TensorFlow","LangChain","LangGraph","LangSmith","OpenAI API","Anthropic API","LM Studio","Ollama","Hugging Face","Pinecone","Chroma","Weaviate","FastAPI","Next.js","React","Laravel"]}],t=document.getElementById("timeline");let i=null;e.length;function s(e){i=e,document.querySelectorAll(".timeline-item").forEach(t=>{const i=t.querySelector(".timeline-bubble");null===e?(t.classList.remove("active"),i.classList.remove("hover-active"),i.setAttribute("aria-expanded","false")):parseInt(t.dataset.phase)===e?(t.classList.add("active"),i.classList.remove("hover-active"),i.setAttribute("aria-expanded","true")):(t.classList.remove("active"),i.classList.remove("hover-active"),i.setAttribute("aria-expanded","false"))})}t.innerHTML="",e.forEach(e=>{const s=document.createElement("div");s.className="timeline-item",s.dataset.phase=e.phase,e.phase===i&&s.classList.add("active"),s.innerHTML=`\n        <div class="timeline-bubble" tabindex="0" role="button" aria-label="View details for ${e.title}" aria-expanded="${e.phase===i}">\n          <div class="bubble-title">${e.title}</div>\n          <div class="bubble-content">\n            <div class="content-section">\n              <h4>SKILLS</h4>\n              <ul class="skills-list">\n                ${e.skills.map(e=>`<li>${e}</li>`).join("")}\n              </ul>\n            </div>\n            <div class="content-section">\n              <h4>TOOLS</h4>\n              <ul class="tools-list">\n                ${e.tools.map(e=>`<li>${e}</li>`).join("")}\n              </ul>\n            </div>\n          </div>\n        </div>\n      `,t.appendChild(s)}),document.querySelectorAll(".timeline-bubble").forEach(e=>{e.addEventListener("click",function(e){e.preventDefault();const t=parseInt(this.closest(".timeline-item").dataset.phase);s(i===t?null:t)}),e.addEventListener("mouseenter",function(){this.closest(".timeline-item").classList.contains("active")||this.classList.add("hover-active")}),e.addEventListener("mouseleave",function(){this.closest(".timeline-item").classList.contains("active")||this.classList.remove("hover-active")}),e.addEventListener("keydown",function(e){if("Enter"===e.key||" "===e.key){e.preventDefault();const t=parseInt(this.closest(".timeline-item").dataset.phase);s(i===t?null:t)}})}),s(null)});